INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (563, 1, '비밀번호 없는 Redis 에 비밀번호 걸기', '지금 Redis 는 비밀번호 없이 열려 있어 접속만 되면 누구나 모든 명령을 쓸 수 있습니다. 서버를 재시작하지 않고 **관리자(기본 사용자) 비밀번호를 `S3cretPw` 로 설정**하세요. 설정한 뒤에는 비밀번호 없이 `PING` 이 거절되고, 비밀번호를 주면 `PONG` 이 나와야 합니다.', '실행 중인 서버의 설정은 `CONFIG SET 항목 값` 으로 바꿉니다. 항목 이름은 `CONFIG GET *pass*` 로 찾아볼 수 있습니다.', 'redis-cli config get ''*pass*''
redis-cli config set requirepass S3cretPw
redis-cli ping                 # NOAUTH Authentication required.
redis-cli -a S3cretPw ping     # PONG

# requirepass 는 기본 사용자(default)의 비밀번호다. CONFIG SET 은 재시작하면 사라지니 영구 적용은 설정 파일에 적는다', '["sh", "-c", "pkill redis-server >/dev/null 2>&1; sleep 1; rm -f /tmp/*.txt /tmp/redis.conf; redis-server --daemonize yes --save '''' --bind 127.0.0.1 --protected-mode yes >/dev/null; sleep 1"]', '["sh", "-c", "( redis-cli ping | grep -q NOAUTH ) && ( [ \\"$(redis-cli -a S3cretPw ping 2>/dev/null)\\" = PONG ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "비밀번호 없이는 거절된다", "cmd": ["sh", "-c", "redis-cli ping | grep -q NOAUTH"]}, {"label": "비밀번호를 주면 PONG 이다", "cmd": ["sh", "-c", "[ \\"$(redis-cli -a S3cretPw ping 2>/dev/null)\\" = PONG ]"]}]', '[{"title": "Redis 보안", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/security/"}, {"title": "Redis ACL", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/security/acl/"}]'),
  (563, 2, 'NOAUTH 오류와 비밀번호를 남기지 않고 접속하기', '관리자 비밀번호(`S3cretPw`)가 걸린 Redis 입니다. 아래를 하세요.
1. 비밀번호 없이 `GET secret` 을 실행해 나온 **오류 메시지를 `/tmp/noauth.txt`** 에 저장
2. 비밀번호를 주고 `secret` 키의 **값을 `/tmp/val.txt`** 에 저장

(`redis-cli -a 비밀번호` 는 명령줄과 셸 기록에 비밀번호가 남고 경고가 나옵니다. 환경 변수 `REDISCLI_AUTH` 에 담아 쓰는 방법도 있습니다.)', '오류는 `redis-cli` 가 보통 화면(표준 출력)에 그대로 찍으므로 `>` 로 저장하세요. 값은 `-a` 옵션이나 `REDISCLI_AUTH=... redis-cli ...` 형태로 인증합니다. 경고는 `2>/dev/null` 로 숨길 수 있습니다.', 'redis-cli get secret > /tmp/noauth.txt
REDISCLI_AUTH=S3cretPw redis-cli get secret > /tmp/val.txt
cat /tmp/noauth.txt /tmp/val.txt

# 오류는 NOAUTH Authentication required. 환경 변수 방식은 ps 목록과 셸 기록에 비밀번호가 안 남는다', '["sh", "-c", "pkill redis-server >/dev/null 2>&1; sleep 1; rm -f /tmp/*.txt /tmp/redis.conf; redis-server --daemonize yes --save '''' --bind 127.0.0.1 --protected-mode yes >/dev/null; sleep 1; redis-cli config set requirepass S3cretPw >/dev/null; REDISCLI_AUTH=S3cretPw redis-cli set app:name etude >/dev/null; REDISCLI_AUTH=S3cretPw redis-cli set secret 42 >/dev/null"]', '["sh", "-c", "( grep -q NOAUTH /tmp/noauth.txt ) && ( [ \\"$(cat /tmp/val.txt)\\" = 42 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "NOAUTH 오류가 기록됐다", "cmd": ["sh", "-c", "grep -q NOAUTH /tmp/noauth.txt"]}, {"label": "값을 읽었다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/val.txt)\\" = 42 ]"]}]', '[{"title": "Redis 보안", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/security/"}, {"title": "Redis ACL", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/security/acl/"}]'),
  (563, 3, '읽기 전용 ACL 사용자 만들기', '관리자(`default`, 비밀번호 `S3cretPw`)로 접속해 **읽기만 가능한 사용자 `reader`** 를 만드세요. 비밀번호는 `readpw`, 모든 키를 읽을 수 있지만 **쓰기 명령은 쓸 수 없어야** 합니다. (사용자는 `on` 상태여야 로그인됩니다.)

끝나면 `reader` 로 `GET app:name` 은 `etude` 가 나오고 `SET` 은 `NOPERM` 으로 거절되어야 합니다.', '`ACL SETUSER 이름 on >비밀번호 ~키패턴 +명령또는카테고리` 형식입니다. 명령 묶음(카테고리)은 `ACL CAT` 으로 볼 수 있습니다. 접속은 `redis-cli --user 이름 --pass 비밀번호` 입니다.', 'REDISCLI_AUTH=S3cretPw redis-cli acl setuser reader on ''>readpw'' ''~*'' +@read
redis-cli --user reader --pass readpw get app:name 2>/dev/null
redis-cli --user reader --pass readpw set a 1 2>/dev/null     # NOPERM

# ~* 모든 키, +@read 읽기 명령 묶음. 쓰기·관리 명령은 허용하지 않은 것이라 거절된다(허용 목록 방식)', '["sh", "-c", "pkill redis-server >/dev/null 2>&1; sleep 1; rm -f /tmp/*.txt /tmp/redis.conf; redis-server --daemonize yes --save '''' --bind 127.0.0.1 --protected-mode yes >/dev/null; sleep 1; redis-cli config set requirepass S3cretPw >/dev/null; REDISCLI_AUTH=S3cretPw redis-cli set app:name etude >/dev/null; REDISCLI_AUTH=S3cretPw redis-cli set secret 42 >/dev/null"]', '["sh", "-c", "( [ \\"$(redis-cli --user reader --pass readpw get app:name 2>/dev/null)\\" = etude ] ) && ( redis-cli --user reader --pass readpw set a 1 2>/dev/null | grep -q NOPERM )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "reader 로 읽을 수 있다", "cmd": ["sh", "-c", "[ \\"$(redis-cli --user reader --pass readpw get app:name 2>/dev/null)\\" = etude ]"]}, {"label": "reader 의 쓰기는 거절된다", "cmd": ["sh", "-c", "redis-cli --user reader --pass readpw set a 1 2>/dev/null | grep -q NOPERM"]}]', '[{"title": "Redis 보안", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/security/"}, {"title": "Redis ACL", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/security/acl/"}]'),
  (563, 4, '키 범위와 위험 명령을 제한한 앱 사용자', '캐시를 쓰는 애플리케이션용 사용자 **`cacheapp`**(비밀번호 `cachepw`)를 만드세요. 조건은 다음과 같습니다.
- **`cache:` 로 시작하는 키만** 다룰 수 있다
- 그 키에서는 읽기·쓰기 등 일반 명령을 쓸 수 있다
- `FLUSHALL`·`CONFIG`·`KEYS` 같은 **위험 명령은 쓸 수 없다**

끝나면 `cacheapp` 로 `SET cache:x 1` 은 `OK`, `SET other:x 1` 과 `FLUSHALL` 은 `NOPERM` 이어야 합니다.', '키 범위는 `~` 로 시작하는 패턴 규칙입니다. 위험 명령은 묶음으로 관리되고 `ACL CAT` 으로 이름을 볼 수 있습니다.', 'REDISCLI_AUTH=S3cretPw redis-cli acl setuser cacheapp on ''>cachepw'' ''~cache:*'' +@all -@dangerous
redis-cli --user cacheapp --pass cachepw set cache:x 1 2>/dev/null     # OK
redis-cli --user cacheapp --pass cachepw set other:x 1 2>/dev/null     # NOPERM (키 범위)
redis-cli --user cacheapp --pass cachepw flushall 2>/dev/null          # NOPERM (위험 명령)

# 앱 계정은 필요한 키와 명령만 허용한다(최소 권한). 키 범위 위반과 명령 위반은 NOPERM 메시지가 다르다', '["sh", "-c", "pkill redis-server >/dev/null 2>&1; sleep 1; rm -f /tmp/*.txt /tmp/redis.conf; redis-server --daemonize yes --save '''' --bind 127.0.0.1 --protected-mode yes >/dev/null; sleep 1; redis-cli config set requirepass S3cretPw >/dev/null; REDISCLI_AUTH=S3cretPw redis-cli set app:name etude >/dev/null; REDISCLI_AUTH=S3cretPw redis-cli set secret 42 >/dev/null"]', '["sh", "-c", "( [ \\"$(redis-cli --user cacheapp --pass cachepw set cache:x 1 2>/dev/null)\\" = OK ] ) && ( redis-cli --user cacheapp --pass cachepw set other:x 1 2>/dev/null | grep -q NOPERM ) && ( redis-cli --user cacheapp --pass cachepw flushall 2>/dev/null | grep -q NOPERM ) && ( redis-cli --user cacheapp --pass cachepw keys \\"*\\" 2>/dev/null | grep -q NOPERM ) && ( redis-cli --user cacheapp --pass cachepw config get save 2>/dev/null | grep -q NOPERM )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "cache 키는 쓸 수 있다", "cmd": ["sh", "-c", "[ \\"$(redis-cli --user cacheapp --pass cachepw set cache:x 1 2>/dev/null)\\" = OK ]"]}, {"label": "다른 키는 거절된다", "cmd": ["sh", "-c", "redis-cli --user cacheapp --pass cachepw set other:x 1 2>/dev/null | grep -q NOPERM"]}, {"label": "FLUSHALL 은 거절된다", "cmd": ["sh", "-c", "redis-cli --user cacheapp --pass cachepw flushall 2>/dev/null | grep -q NOPERM"]}, {"label": "KEYS 도 거절된다", "cmd": ["sh", "-c", "redis-cli --user cacheapp --pass cachepw keys \\"*\\" 2>/dev/null | grep -q NOPERM"]}, {"label": "CONFIG 도 거절된다", "cmd": ["sh", "-c", "redis-cli --user cacheapp --pass cachepw config get save 2>/dev/null | grep -q NOPERM"]}]', '[{"title": "Redis 보안", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/security/"}, {"title": "Redis ACL", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/security/acl/"}]'),
  (563, 5, 'bind 와 protected-mode 읽기', '서버가 **어느 주소에서 접속을 받는지**는 `bind`, 비밀번호도 없고 bind 도 안 정했는데 외부에서 오는 접속을 **거절하는 안전장치**는 `protected-mode` 입니다. 지금 서버의 두 설정값을 저장하세요. (값만)
- `/tmp/bind.txt` : `bind` 값
- `/tmp/pm.txt` : `protected-mode` 값', '`redis-cli config get 항목` 은 항목 이름과 값이 두 줄로 나옵니다. `tail -1` 로 값 줄만 고르세요.', 'redis-cli config get bind | tail -1 > /tmp/bind.txt
redis-cli config get protected-mode | tail -1 > /tmp/pm.txt
cat /tmp/bind.txt /tmp/pm.txt

# bind 127.0.0.1 은 같은 서버 안에서만 접속된다. 외부에서 쓰려면 bind 를 바꾸되 반드시 비밀번호·ACL·방화벽과 함께 한다', '["sh", "-c", "pkill redis-server >/dev/null 2>&1; sleep 1; rm -f /tmp/*.txt /tmp/redis.conf; redis-server --daemonize yes --save '''' --bind 127.0.0.1 --protected-mode yes >/dev/null; sleep 1"]', '["sh", "-c", "( [ \\"$(cat /tmp/bind.txt)\\" = 127.0.0.1 ] ) && ( [ \\"$(cat /tmp/pm.txt)\\" = yes ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "bind 가 127.0.0.1 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/bind.txt)\\" = 127.0.0.1 ]"]}, {"label": "protected-mode 가 yes 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/pm.txt)\\" = yes ]"]}]', '[{"title": "Redis 보안", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/security/"}, {"title": "Redis ACL", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/security/acl/"}]'),
  (563, 6, '설정 파일로 영구 적용하기', '`CONFIG SET` 은 재시작하면 사라집니다. **설정 파일** `/tmp/redis.conf` 를 만들어 아래 설정으로 **새 Redis 를 띄우세요.**
- 포트 `6380`
- `127.0.0.1` 에서만 접속 받기
- 비밀번호 `FilePw1`
- 백그라운드로 실행 (`daemonize yes`)

(기존 서버와 포트가 달라 함께 떠 있어도 됩니다. 서버는 `redis-server 설정파일경로` 로 띄웁니다.)', '설정 파일은 한 줄에 `항목 값` 형식입니다. 항목 이름은 `CONFIG GET` 에서 쓰던 것과 같습니다. 접속 확인은 `redis-cli -p 6380 ...` 입니다.', 'printf ''port 6380\\nbind 127.0.0.1\\nrequirepass FilePw1\\ndaemonize yes\\n'' > /tmp/redis.conf
redis-server /tmp/redis.conf
sleep 1
redis-cli -p 6380 ping                    # NOAUTH
redis-cli -p 6380 -a FilePw1 ping 2>/dev/null   # PONG

# 설정 파일은 재시작 후에도 유지된다. 운영에서는 이 파일의 권한(600)도 제한한다. 비밀번호가 평문으로 들어 있기 때문', '["sh", "-c", "pkill redis-server >/dev/null 2>&1; sleep 1; rm -f /tmp/*.txt /tmp/redis.conf; redis-server --daemonize yes --save '''' --bind 127.0.0.1 --protected-mode yes >/dev/null; sleep 1"]', '["sh", "-c", "( grep -q \\"^requirepass\\" /tmp/redis.conf ) && ( redis-cli -p 6380 ping | grep -q NOAUTH ) && ( [ \\"$(redis-cli -p 6380 -a FilePw1 ping 2>/dev/null)\\" = PONG ] ) && ( [ \\"$(redis-cli -p 6380 -a FilePw1 config get bind 2>/dev/null | tail -1)\\" = 127.0.0.1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "설정 파일에 requirepass 가 있다", "cmd": ["sh", "-c", "grep -q \\"^requirepass\\" /tmp/redis.conf"]}, {"label": "6380 서버가 비밀번호 없이는 거절한다", "cmd": ["sh", "-c", "redis-cli -p 6380 ping | grep -q NOAUTH"]}, {"label": "비밀번호로 PONG 이다", "cmd": ["sh", "-c", "[ \\"$(redis-cli -p 6380 -a FilePw1 ping 2>/dev/null)\\" = PONG ]"]}, {"label": "bind 가 127.0.0.1 이다", "cmd": ["sh", "-c", "[ \\"$(redis-cli -p 6380 -a FilePw1 config get bind 2>/dev/null | tail -1)\\" = 127.0.0.1 ]"]}]', '[{"title": "Redis 보안", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/security/"}, {"title": "Redis ACL", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/security/acl/"}]'),
  (563, 7, '안 쓰는 ACL 사용자 정리하기', '`alice`, `bob`, `tmpuser` 세 사용자가 만들어져 있습니다. 임시로 만든 **`tmpuser` 를 삭제**하고, 삭제한 뒤 남아 있는 **사용자 이름 목록**을 `/tmp/users.txt` 에 한 줄에 하나씩 저장하세요. (관리자 비밀번호 `S3cretPw` 로 접속)', '`ACL USERS` 는 사용자 이름만 한 줄씩, `ACL LIST` 는 규칙까지 보여 줍니다. 삭제 명령은 `ACL DEL...` 로 시작합니다.', 'REDISCLI_AUTH=S3cretPw redis-cli acl deluser tmpuser
REDISCLI_AUTH=S3cretPw redis-cli acl users > /tmp/users.txt
cat /tmp/users.txt

# 퇴사·종료된 계정은 비활성화(off)하거나 삭제한다. 쓰지 않는 계정이 남아 있으면 그 비밀번호가 유출됐을 때 공격 통로가 된다', '["sh", "-c", "pkill redis-server >/dev/null 2>&1; sleep 1; rm -f /tmp/*.txt /tmp/redis.conf; redis-server --daemonize yes --save '''' --bind 127.0.0.1 --protected-mode yes >/dev/null; sleep 1; redis-cli config set requirepass S3cretPw >/dev/null; REDISCLI_AUTH=S3cretPw redis-cli set app:name etude >/dev/null; REDISCLI_AUTH=S3cretPw redis-cli set secret 42 >/dev/null; for u in alice bob tmpuser; do REDISCLI_AUTH=S3cretPw redis-cli acl setuser $u on ''>pw1'' ''~*'' +@read >/dev/null; done"]', '["sh", "-c", "( ! REDISCLI_AUTH=S3cretPw redis-cli acl users | grep -qx tmpuser ) && ( [ \\"$(sort /tmp/users.txt | tr ''\\\\n'' '' '')\\" = \\"alice bob default \\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "tmpuser 가 삭제됐다", "cmd": ["sh", "-c", "! REDISCLI_AUTH=S3cretPw redis-cli acl users | grep -qx tmpuser"]}, {"label": "나머지 사용자 목록이 저장됐다", "cmd": ["sh", "-c", "[ \\"$(sort /tmp/users.txt | tr ''\\\\n'' '' '')\\" = \\"alice bob default \\" ]"]}]', '[{"title": "Redis 보안", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/security/"}, {"title": "Redis ACL", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/security/acl/"}]'),
  (563, 8, 'protected-mode 가 하는 일', 'Redis 의 `protected-mode yes`(기본값)는 어떤 상황에서 외부 접속을 막아 주나요?', '비밀번호도 bind 설정도 없다면 어떤 접속이 위험한지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["인증 설정과 bind 가 모두 없을 때 127.0.0.1 이외의 접속을 거절한다", "모든 접속의 통신 내용을 자동으로 암호화해 도청을 막아 준다", "위험한 명령(FLUSHALL 등)을 모든 사용자에게서 영구히 막는다", "디스크에 쓰는 RDB 파일을 읽지 못하도록 파일 권한을 잠근다"]', 0, 'protected-mode 는 인증 설정(requirepass/ACL)과 bind 가 모두 없는 서버가 인터넷에 그대로 노출되는 것을 막는 안전장치입니다. 비밀번호를 걸거나 bind 를 정하면 외부 접속이 허용됩니다. 암호화는 TLS, 명령 제한은 ACL 의 몫입니다.', NULL, NULL, NULL, NULL),
  (563, 9, 'requirepass 와 ACL 의 관계', 'Redis 6 이상에서 `requirepass 비밀번호` 설정은 ACL 관점에서 무엇과 같은가요?', '사용자 이름 없이 비밀번호만으로 인증하던 옛 방식이 ACL 에서 어떻게 이어지는지 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["새 관리자 사용자 admin 을 자동으로 만드는 것이다", "ACL 을 모두 끄고 비밀번호 하나만 쓰게 하는 것이다", "읽기 전용 사용자의 비밀번호를 정하는 것이다", "기본 사용자(default)의 비밀번호를 설정하는 것과 같다"]', 3, 'requirepass 는 ACL 의 `default` 사용자에게 비밀번호를 거는 것과 같습니다. 별도 사용자(`reader`, `cacheapp` 등)를 만들어 쓰면 default 와 별개로 권한을 나눌 수 있고, requirepass 와 ACL 은 함께 쓰입니다.', NULL, NULL, NULL, NULL),
  (563, 10, '읽기 전용 권한 묶음', '`reader` 사용자에게 모든 읽기 명령만 허용하려고 합니다. 빈칸의 명령 카테고리를 채우세요.', '읽기 명령 묶음의 이름은 골뱅이(@)로 시작합니다.', NULL, NULL, '[]', 'fill', '["@read", "@write", "@all", "@admin"]', NULL, '`@read` 는 GET 같은 읽기 명령 묶음입니다. `@write` 는 쓰기, `@admin` 은 관리 명령, `@all` 은 모든 명령을 허용하므로 읽기 전용이 되지 않습니다.', '[0]', 'ACL SETUSER reader on >readpw ~* +{0}', NULL, NULL),
  (563, 11, '앱용 Redis 계정 만들기 순서', '새 애플리케이션이 Redis 를 쓰게 되었습니다. 앱 전용 계정을 만들어 적용하는 순서를 놓으세요. 권한이 부족하면 NOPERM 으로 바로 드러납니다.', '앱에 배포하기 전에 무엇이 끝나 있어야 하는지 생각해 보세요.', NULL, NULL, '[]', 'order', '["ACL GETUSER 또는 접속 테스트로 허용·거절이 의도대로인지 확인", "앱의 접속 정보에 새 계정과 비밀번호를 설정해 배포", "ACL SETUSER 로 필요한 키 범위와 명령만 허용하는 계정 생성", "앱이 어떤 키와 명령을 쓰는지 파악"]', NULL, '앱이 쓰는 키 패턴과 명령을 먼저 파악하고, 그 범위만 허용하는 계정을 ACL SETUSER 로 만듭니다. 접속 테스트로 허용과 거절을 확인한 뒤 앱의 접속 정보에 넣어 배포합니다. 권한이 부족하면 NOPERM 으로 바로 드러나므로 배포 전에 확인합니다.', '[3, 2, 0, 1]', NULL, NULL, NULL);
